package io.gluonify.plasma.quarkus.mcp;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.ArrayList;
import java.util.List;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.ObjectMapper;

/** Declarations checked at startup: an invalid one stops the application. */
class McpRegistryTest {
    static final ObjectMapper M = new ObjectMapper();

    static String refusal(final Object... toolboxes) {
        final var declared = List.of(toolboxes);
        return assertThrows(IllegalStateException.class, () -> McpRegistry.of(declared, M, w -> {})).getMessage();
    }

    static class BadName implements McpToolbox {
        @McpTool(name = "Order-Stats", description = "x")
        public String t() { return ""; }
    }

    static class TooLong implements McpToolbox {
        @McpTool(name = "a12345678901234567890123456789012345678901", description = "x") // 42 characters
        public String t() { return ""; }
    }

    static class Twice implements McpToolbox {
        @McpTool(name = "same", description = "x")
        public String a() { return ""; }

        @McpTool(name = "same", description = "y")
        public String b() { return ""; }
    }

    static class NoDescription implements McpToolbox {
        @McpTool(description = " ")
        public String t() { return ""; }
    }

    static class TwoArguments implements McpToolbox {
        @McpTool(description = "x")
        public String t(final String a, final String b) { return ""; }
    }

    static class NotObjectSchema implements McpToolbox {
        @McpTool(description = "x", inputSchema = "{\"type\":\"string\"}")
        public String t() { return ""; }
    }

    static class InvalidSchema implements McpToolbox {
        @McpTool(description = "x", inputSchema = "{oops")
        public String t() { return ""; }
    }

    static class NotPublic implements McpToolbox {
        @McpTool(description = "x")
        String t() { return ""; }
    }

    static class BigSchema implements McpToolbox {
        static final String DESCRIPTION = ""; // 17 KiB, a constant expression

        @McpTool(description = "x", inputSchema = "{\"type\":\"object\",\"description\":\"" + DESCRIPTION + "\"}")
        public String t() { return ""; }
    }

    static class Empty implements McpToolbox {}

    @Test
    void nameGrammar() {
        assertTrue(refusal(new BadName()).startsWith("invalid MCP tool name 'Order-Stats'"));
        assertTrue(refusal(new TooLong()).startsWith("invalid MCP tool name"));
        assertEquals("order_stats", McpRegistry.snake("orderStats"));
        assertEquals("httpstatus", McpRegistry.snake("HTTPStatus"));
        assertEquals("a_b2_c", McpRegistry.snake("aB2C"));
    }

    @Test
    void declarationErrors() {
        assertEquals("MCP tool declared twice: same", refusal(new Twice()));
        assertTrue(refusal(new NoDescription()).endsWith("a description is required"));
        assertTrue(refusal(new TwoArguments()).contains("one arguments parameter"));
        assertTrue(refusal(new NotObjectSchema()).endsWith("must be an object schema (\"type\": \"object\")"));
        assertTrue(refusal(new InvalidSchema()).endsWith("not valid JSON"));
        assertTrue(refusal(new NotPublic()).endsWith("the method must be public"));
        assertTrue(refusal(new BigSchema()).endsWith("larger than 16 KiB"));
    }

    @Test
    void atMostFiftyTools() {
        assertEquals(50, McpRegistry.of(List.of(new ManyTools.First30(), new ManyTools.Next20()), M, w -> {}).size());
        assertEquals("at most 50 MCP tools per application", refusal(new ManyTools.First30(), new ManyTools.Next20(), new ManyTools.One()));
    }

    @Test
    void aToolboxWithoutToolIsReported() {
        final List<String> warnings = new ArrayList<>();
        assertEquals(0, McpRegistry.of(List.of(new Empty()), M, warnings::add).size());
        assertEquals(1, warnings.size());
        assertTrue(warnings.get(0).contains("@RegisterForReflection"));
    }
}
